package net.hivel.islandsrpg.listener;
import net.hivel.islandsrpg.IslandsRPGPlugin; import org.bukkit.entity.*; import org.bukkit.event.*; import org.bukkit.event.entity.*;
public class MobListener implements Listener { private final IslandsRPGPlugin p; public MobListener(IslandsRPGPlugin p){this.p=p;} @EventHandler public void death(EntityDeathEvent e){LivingEntity le=e.getEntity(); if(!p.mobs().isCustom(le))return; Player killer=le.getKiller(); String id=p.mobs().id(le); if(killer!=null){ if(p.bosses().isBoss(le)){var b=p.bosses().get(id); if(b!=null){p.levels().addXp(killer,b.xp()); p.currency().addMoney(killer,b.money()); p.currency().addFragments(killer,b.fragments()); p.drops().roll(killer,b.drops().values(),le.getLocation()); p.quests().handleBossKill(killer,id); var d=p.data().get(killer); d.bossKills.merge(id,1,Integer::sum);}} else {var m=p.mobs().get(id); if(m!=null){p.levels().addXp(killer,m.xp()); p.currency().addMoney(killer,m.money()); p.currency().addFragments(killer,m.fragments()); p.drops().roll(killer,m.drops().values(),le.getLocation()); p.quests().handleKill(killer,id); var d=p.data().get(killer); d.kills.merge(id,1,Integer::sum);}}} p.bossBars().remove(le);} @EventHandler public void generic(EntityDamageEvent e){if(e.getEntity() instanceof LivingEntity le && p.mobs().isCustom(le)){String id=p.mobs().id(le); var m=p.mobs().get(id); if(m!=null)p.getServer().getScheduler().runTaskLater(p,()->p.mobs().updateName(le,m.displayName(),m.health()),1); var b=p.bosses().get(id); if(b!=null)p.getServer().getScheduler().runTaskLater(p,()->{p.mobs().updateName(le,b.displayName(),b.health()); p.bossBars().update(le,b);},1);}} @EventHandler public void despawn(EntityRemoveEvent e){ if(e.getEntity() instanceof LivingEntity le && p.bosses().isBoss(le)) p.bossBars().remove(le);} }
